import sys
import math

def count_x_leq(X):
    limit_a = int(math.isqrt(X))
    total = 0
    for a in range(1, limit_a + 1):
        a2 = a * a
        max_b = int(math.isqrt(X + a2))
        if max_b <= a:
            continue
        total += max_b - a
    return total

def find_nth(N):
    lo, hi = 1, 10**18
    while lo < hi:
        mid = (lo + hi) // 2
        if count_x_leq(mid) >= N:
            hi = mid
        else:
            lo = mid + 1
    return lo

def main():
    N = int(sys.stdin.readline().strip())
    print(find_nth(N))

