def count_suitable(x):
    limit = int(math.isqrt(2 * x))
    cnt = 0
    for a in range(1, limit + 1):
        num = 2 * x - a * a
        den = 2 * a
        if num <= 0:
            continue
        b = num // den
        if b <= a:
            continue
        if a * b + (b * b - a * a) // 2 == x:
            cnt += 1
    return cnt

