import sys
import math

def count_suitable(x):
    # Count number of suitable integers <= x
    limit = int(math.isqrt(x))
    total = 0
    for a in range(1, limit + 1):
        # b must satisfy:
        # a^2 + b^2 > x  => b > sqrt(x - a^2)
        # a^2 + 2ab <= x => b <= (x - a^2) / (2a)
        # and b > a
        t = x - a * a
        if t <= 0:
            continue
        b_min = max(a + 1, int(math.isqrt(t)) + 1)
        b_max = t // (2 * a)
        if b_max >= b_min:
            total += b_max - b_min + 1
    return total

def find_nth(n):
    lo, hi = 1, 10**18
    while lo < hi:
        mid = (lo + hi) // 2
        if count_suitable(mid) >= n:
            hi = mid
        else:
            lo = mid + 1
    return lo

