import sys
import math

def count_suitable(x):
    # count number of (a,b) with a<b, a,b positive integers
    # such that a^2 + b^2 is a perfect square and a*b = x
    cnt = 0
    limit = int(math.isqrt(x))
    for a in range(1, limit + 1):
        if x % a != 0:
            continue
        b = x // a
        if a >= b:
            continue
        c2 = a * a + b * b
        c = int(math.isqrt(c2))
        if c * c == c2:
            cnt += 1
    return cnt

def find_nth(n):
    lo, hi = 1, 10**18
    while lo < hi:
        mid = (lo + hi) // 2
        if count_suitable(mid) >= n:
            hi = mid
        else:
            lo = mid + 1
    return lo

